#!/usr/bin/env python3
"""Emit one compact, normalized smartctl JSON event per discovered device."""
import json
import os
import subprocess
import time

SMARTCTL = os.environ.get("SMARTCTL", "/usr/sbin/smartctl")
TIMEOUT_SECONDS = 60


def emit(event):
    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)


def run_smartctl(arguments):
    try:
        return subprocess.run(
            [SMARTCTL] + arguments,
            check=False,
            capture_output=True,
            text=True,
            timeout=TIMEOUT_SECONDS,
            env={"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LC_ALL": "C"},
        )
    except (FileNotFoundError, PermissionError, subprocess.TimeoutExpired) as error:
        return error


def parse_json(completed):
    try:
        payload = json.loads(completed.stdout)
        return payload if isinstance(payload, dict) else None
    except (json.JSONDecodeError, TypeError):
        return None


def error_text(value):
    text = str(value)
    if isinstance(value, subprocess.CompletedProcess):
        text = value.stderr or "smartctl returned non-JSON output"
    return " ".join(text.split())[:240]


scan = run_smartctl(["--scan-open", "--json"])
if not isinstance(scan, subprocess.CompletedProcess):
    emit({"event_version": 1, "collector": "smartctl_json_v1", "collector_status": "scan_error", "observed_at_epoch": int(time.time()), "error_detail": error_text(scan)})
    raise SystemExit(0)

scan_payload = parse_json(scan)
devices = scan_payload.get("devices", []) if scan_payload else []
if not isinstance(devices, list) or not devices:
    emit({"event_version": 1, "collector": "smartctl_json_v1", "collector_status": "no_devices_discovered", "observed_at_epoch": int(time.time()), "smartctl_exit_status": scan.returncode, "error_detail": error_text(scan)})
    raise SystemExit(0)

for discovered in devices:
    if not isinstance(discovered, dict) or not discovered.get("name"):
        continue
    name = str(discovered["name"])
    device_type = str(discovered.get("type") or "auto")
    arguments = ["--health", "--attributes", "--json"]
    if device_type != "auto":
        arguments += ["--device", device_type]
    arguments.append(name)
    completed = run_smartctl(arguments)
    common = {"event_version": 1, "collector": "smartctl_json_v1", "observed_at_epoch": int(time.time()), "device": name, "device_type": device_type}
    if not isinstance(completed, subprocess.CompletedProcess):
        emit(dict(common, collector_status="command_error", error_detail=error_text(completed)))
        continue
    payload = parse_json(completed)
    if payload is None:
        emit(dict(common, collector_status="invalid_json", smartctl_exit_status=completed.returncode, error_detail=error_text(completed)))
        continue
    smartctl_block = payload.get("smartctl") if isinstance(payload.get("smartctl"), dict) else {}
    exit_status = smartctl_block.get("exit_status", completed.returncode)
    try:
        exit_status = int(exit_status)
    except (TypeError, ValueError):
        exit_status = completed.returncode
    report_device = payload.get("device") if isinstance(payload.get("device"), dict) else {}
    protocol = str(report_device.get("protocol") or discovered.get("protocol") or "unknown")
    passed = payload.get("smart_status", {}).get("passed") if isinstance(payload.get("smart_status"), dict) else None
    nvme_status = payload.get("smart_status", {}).get("nvme") if isinstance(payload.get("smart_status"), dict) else None
    critical_warning = nvme_status.get("value") if isinstance(nvme_status, dict) else None
    nvme_log = payload.get("nvme_smart_health_information_log")
    if critical_warning is None and isinstance(nvme_log, dict):
        critical_warning = nvme_log.get("critical_warning")
    try:
        critical_warning = int(critical_warning) if critical_warning is not None else None
    except (TypeError, ValueError):
        critical_warning = None
    command_error_bits = exit_status & 7
    if command_error_bits:
        status = "command_error"
    elif not isinstance(passed, bool):
        status = "smart_status_unavailable"
    elif protocol.upper() == "NVME" and critical_warning is None:
        status = "contract_incomplete"
    else:
        status = "ok"
    serial = payload.get("serial_number")
    event = dict(
        common,
        collector_status=status,
        device_key=str(serial or name),
        device_type=str(report_device.get("type") or device_type),
        device_protocol=protocol,
        model_name=payload.get("model_name"),
        serial_number=serial,
        smartctl_exit_status=exit_status,
        smart_passed=int(passed) if isinstance(passed, bool) else None,
        attribute_threshold_failed=int(protocol.upper() == "ATA" and bool(exit_status & 16)),
        nvme_critical_warning=critical_warning,
    )
    if status != "ok":
        event["error_detail"] = error_text(completed)
    emit(event)
